#!/usr/bin/env python3
"""Rebuild appendix tables from saved evidence; never run models or modify raw data."""
from pathlib import Path
import csv, hashlib, importlib.util, json, statistics
ROOT=Path(__file__).resolve().parents[4]
OUT=Path(__file__).resolve().parent
SOURCES={}
def source(relative):
 p=ROOT/relative;SOURCES[relative]=hashlib.sha256(p.read_bytes()).hexdigest();return p
def csvrows(relative): return list(csv.DictReader(source(relative).open()))
def table(name,columns,header,rows):
 s=['% Generated by appendix/build_tables.py; source hashes in table_sources.json.',r'\begin{tabular}{'+columns+'}',r'\toprule',' & '.join(header)+r' \\',r'\midrule']
 s+=[' & '.join(map(str,r))+r' \\' for r in rows];s += [r'\bottomrule',r'\end{tabular}']
 (OUT/name).write_text('\n'.join(s)+'\n')
q=csvrows('paper/shared/evidence/raw/image_quality.csv');f=csvrows('paper/shared/evidence/raw/feature_similarity.csv')
rows=[]
for scene in sorted({r['scene_id'] for r in q})+['All']:
 a=[r for r in q if scene=='All' or r['scene_id']==scene];b=[r for r in f if scene=='All' or r['scene_id']==scene]
 assert {(r['scene_id'],r['angle']) for r in a}=={(r['scene_id'],r['angle']) for r in b}
 vals=[statistics.mean(float(r[k]) for r in pool) for pool,k in [(a,'psnr'),(a,'ssim'),(a,'lpips'),(b,'clip_cosine'),(b,'dino_cosine')]]
 rows.append([scene.replace('chestofdrawers_','Chest ').replace('_',r'\_'),len(a),f'{vals[0]:.2f}']+[f'{v:.3f}' for v in vals[1:]])
table('proxy_table.tex','lrrrrrr',['Asset','Pairs','PSNR','SSIM','LPIPS','CLIP','DINOv2'],rows)
spec=importlib.util.spec_from_file_location('iclr_analysis',source('paper/shared/evidence/experiments/11_iclr_model_behavior/analyze.py'));m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
a=json.loads(source('paper/shared/evidence/raw/iclr_model_behavior/analysis_v1/results.json').read_text())
rows=[]
for r in a['runs']:
 if r['pool']=='clean15':
  s=r['score'];rows.append([r['model'],s['n_pairs'],s['original']['valid_point_n'],s['converted']['valid_point_n'],s['original']['hit_n'],s['converted']['hit_n'],s['flip_n']])
table('clean_table.tex','lrrrrrr',['Model','$N$','$V_O$','$V_C$','$H_O$','$H_C$','Flips'],rows)
rows=[]
for label,sub,frame in [('Gemma4 pilot','probes/gemma4_pass_only_predictions.jsonl','pixel'),('Qwen2.5 JSON pilot','probes/qwen25_pass_only_predictions.jsonl','normalized_1000'),('Qwen2.5 text pilot','probes/qwen25_pass_only_structured_predictions.jsonl','normalized_1000'),('Gemma4 zoom','zoom_stress_probes/gemma4_zoom_stress_predictions.jsonl','normalized_1000'),('Qwen2.5 zoom','zoom_stress_probes/qwen25_zoom_stress_structured_predictions.jsonl','normalized_1000')]:
 p=source('paper/shared/evidence/raw/grscene_vlm_grounding/'+sub);rr=m.load_rows(p);s=m.summarize(rr,frame);alt=m.summarize(rr,'normalized_1000' if frame=='pixel' else 'pixel')
 rows.append([label,s['n_pairs'],f"{s['original']['valid_point_n']}/{s['converted']['valid_point_n']}",f"{s['original']['hit_n']}/{s['converted']['hit_n']}",f"{alt['original']['hit_n']}/{alt['converted']['hit_n']}"])
table('historical_table.tex','lrrrr',['Run','$N$','$V_O/V_C$','Requested hits O/C','Other frame O/C'],rows)
rows=[]
for r in csvrows('paper/shared/tables/material_effect_baseline_summary.csv'):
 if r['condition']=='original_MDL':
  effect=r['effect'];allr=csvrows('paper/shared/tables/material_effect_baseline_summary.csv');d={x['condition']:x for x in allr if x['effect']==effect}
  names={'clearcoat':'Clearcoat fixture','procedural_texture':'Procedural fixture','opacity_transparency':'Opacity / transparency','normal_bump':'Normal / bump','displacement_height':'Displacement / height','emission':'Emission'}
  rows.append([names[effect],r['sample_count']]+[f"{d[c]['static_gate_passed_count']}/{r['sample_count']}" for c in ['original_MDL','existing_noMDL','nvidia_asset_converter_preview_or_bake']])
table('material_table.tex','lrrrr',['Effect','$N$','Original','ConvertAsset','NVIDIA'],rows)
ci={r['metric_id']:r for r in csvrows('paper/shared/tables/reviewer_closure_paired_ci.csv') if r['evidence_id']=='internnav_official_val_unseen_99'}
rows=[]
for key,name in [('SR','SR (\\%)'),('SPL','SPL (\\%)'),('OS','Oracle success (\\%)'),('NE','Navigation error'),('TL','Trajectory length'),('steps','Action steps'),('FR','Fall rate'),('StR','Stuck rate')]:
 s=a['navigation']['metrics'][key];scale=100 if key in ('SR','SPL','OS') else 1
 rows.append([name,f"{s['original_mean']*scale:.3f}",f"{s['modified_mean']*scale:.3f}",f"{s['mean_delta_modified_minus_original']*scale:+.3f}", (f"[{float(ci[key]['ci95_low'])*scale:.3f}, {float(ci[key]['ci95_high'])*scale:.3f}]" if key in ci else "---")])
table('navigation_full_table.tex','lrrrr',['Metric','Original','Converted','$\\Delta$',r'95\% paired CI'],rows)
rows=[]
for r in csvrows('paper/shared/tables/official_scene_performance_summary.csv'):
 if r['row_type']=='aggregate':
  rows.append(['Original' if r['condition']=='original_mdl' else 'Converted',r['success_count']+'/9',r['total_ready_s'],r['warmup_fps'],r['gpu_memory_mb']])
table('navigation_load_table.tex','lrrrr',['Condition','Loads','Ready time (s)','Warm-up FPS','GPU memory (MB)'],rows)
for run in a['runs']:
 if run['pool']=='clean15': source(run['source'])
for group in a['sampling']:
 for raw in group['sources']: source(raw)
for raw in ['paper/shared/evidence/experiments/07_internnav_vln_downstream/analyze_paired_metrics.py','paper/shared/evidence/raw/reviewer_closure_package/vlm_coordinate_baseline_summary.json','paper/shared/evidence/raw/iclr_model_behavior/interventions_clean_v2/manifest.json','paper/shared/evidence/experiments/11_iclr_model_behavior/prepare_interventions.py','paper/shared/evidence/raw/material_effect_baseline/baseline_conversion_manifest.json','paper/shared/evidence/raw/material_effect_baseline/supplemental_conversion_manifest.json','paper/shared/evidence/raw/internnav_vln_downstream/official_val_unseen_99/paired_99_summary.json','paper/shared/evidence/raw/official_scene_submission_closure/official_scene_performance_runs.csv','paper/shared/evidence/raw/reviewer_closure_package/reviewer_closure_statistical_summary.json','paper/venues/iclr27/appendix/build_tables.py']:
 source(raw)
(OUT/'table_sources.json').write_text(json.dumps({'generator':'appendix/build_tables.py','sources':SOURCES,'note':'Saved-data reanalysis only; no raw files modified.'},indent=2)+'\n')
print('Built 6 appendix tables from',len(SOURCES),'sources')
